-- Needs migrations/0052_innovation_talk_details.sql first (the hall column).
-- Safe to run again: it sets the same values each time.
-- 21 talks get a time. Agenda slots with no single talk to match: IIT Bombay (no speaker in the talks list); Shri Vivek Khandekar (IFS), Maharashtra Forest Department (2 talks in the agenda: set the time by hand); NoBroker (the agenda names no speaker for its slot).

-- Innovation Talks are in the Expo Hall (Aryabhata Theatre), unless a hall is already set
-- or the agenda puts the talk in another hall (CGI, Maharashtra Forest Department, NoBroker).
UPDATE innovation_talks SET hall = 'Aryabhata Theatre' WHERE event_id = 1 AND trim(ifnull(hall, '')) = '' AND company NOT IN ('CGI', 'Maharashtra Forest Department', 'NoBroker');

